Translate the following Java 8 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String lineCount = scanner.nextLine();
        String inputString = scanner.nextLine();

        int maxLength = 0;
        int countTokens = 0;
        int index = 0;
        int lastParenIndex = 0;

        while (index < inputString.lastIndexOf(')')) {
            int startIdx = inputString.indexOf('(', index);
            int endIdx = inputString.indexOf(')', startIdx);
            String segment = inputString.substring(lastParenIndex, startIdx);
            StringTokenizer tokenizer = new StringTokenizer(segment, "_");
            while (tokenizer.hasMoreTokens()) {
                int tokenLength = tokenizer.nextToken().length();
                if (tokenLength > maxLength) {
                    maxLength = tokenLength;
                }
            }
            String inside = inputString.substring(startIdx + 1, endIdx);
            StringTokenizer innerTokenizer = new StringTokenizer(inside, "_");
            while (innerTokenizer.hasMoreTokens()) {
                String token = innerTokenizer.nextToken();
                if (!token.isEmpty()) {
                    countTokens++;
                }
            }
            lastParenIndex = endIdx + 1;
            index = endIdx;
        }

        String remaining = inputString.substring(lastParenIndex);
        StringTokenizer remainingTokenizer = new StringTokenizer(remaining, "_");
        while (remainingTokenizer.hasMoreTokens()) {
            int tokenLength = remainingTokenizer.nextToken().length();
            if (tokenLength > maxLength) {
                maxLength = tokenLength;
            }
        }

        System.out.println(maxLength + " " + countTokens);
    }
}
